export enum IncidentSeverity {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
  CRITICAL = 'CRITICAL',
}

export function isIncidentSeverityUrgent(severity: IncidentSeverity): boolean {
  return severity === IncidentSeverity.HIGH || severity === IncidentSeverity.CRITICAL;
}

